/* gemm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

#if defined(_OPENMP)
#include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* 
   * Parallelize the workload via OpenMP over the outer tiled loop blocks.
   * `collapse(2)` ensures that both `ii` and `jj` iterations are combined 
   * into one large thread iteration space for perfect workload distribution.
   */
  #pragma omp parallel for collapse(2)
  for (int ii = 0; ii < _PB_NI; ii += 64) {
    for (int jj = 0; jj < _PB_NJ; jj += 256) {

      int i_max = (ii + 64 < _PB_NI) ? (ii + 64) : _PB_NI;
      int j_max = (jj + 256 < _PB_NJ) ? (jj + 256) : _PB_NJ;

      /* Phase 1: Pre-scale thread's local block of C by beta */
      for (int i = ii; i < i_max; i++) {
        #pragma GCC ivdep
        for (int j = jj; j < j_max; j++) {
          C[i][j] *= beta;
        }
      }

      /* Standard GEMM algebraic optimization, skip if alpha equates to zero */
      if (alpha == (DATA_TYPE)0.0) continue;

      /* Phase 2: Compute alpha * A * B, Tiled over K dimension */
      for (int kk = 0; kk < _PB_NK; kk += 128) {
        int k_max = (kk + 128 < _PB_NK) ? (kk + 128) : _PB_NK;

        int i = ii;
        for (; i <= i_max - 4; i += 4) {
          int k = kk;

          /* 4x4 Register Blocking Micro-kernel */
          for (; k <= k_max - 4; k += 4) {
            DATA_TYPE a00 = alpha * A[i+0][k+0]; DATA_TYPE a01 = alpha * A[i+0][k+1];
            DATA_TYPE a02 = alpha * A[i+0][k+2]; DATA_TYPE a03 = alpha * A[i+0][k+3];

            DATA_TYPE a10 = alpha * A[i+1][k+0]; DATA_TYPE a11 = alpha * A[i+1][k+1];
            DATA_TYPE a12 = alpha * A[i+1][k+2]; DATA_TYPE a13 = alpha * A[i+1][k+3];

            DATA_TYPE a20 = alpha * A[i+2][k+0]; DATA_TYPE a21 = alpha * A[i+2][k+1];
            DATA_TYPE a22 = alpha * A[i+2][k+2]; DATA_TYPE a23 = alpha * A[i+2][k+3];

            DATA_TYPE a30 = alpha * A[i+3][k+0]; DATA_TYPE a31 = alpha * A[i+3][k+1];
            DATA_TYPE a32 = alpha * A[i+3][k+2]; DATA_TYPE a33 = alpha * A[i+3][k+3];

            #pragma GCC ivdep
            for (int j = jj; j < j_max; j++) {
              DATA_TYPE c0 = C[i+0][j]; DATA_TYPE c1 = C[i+1][j];
              DATA_TYPE c2 = C[i+2][j]; DATA_TYPE c3 = C[i+3][j];

              DATA_TYPE b0 = B[k+0][j];
              c0 += a00 * b0; c1 += a10 * b0; c2 += a20 * b0; c3 += a30 * b0;

              DATA_TYPE b1 = B[k+1][j];
              c0 += a01 * b1; c1 += a11 * b1; c2 += a21 * b1; c3 += a31 * b1;

              DATA_TYPE b2 = B[k+2][j];
              c0 += a02 * b2; c1 += a12 * b2; c2 += a22 * b2; c3 += a32 * b2;

              DATA_TYPE b3 = B[k+3][j];
              c0 += a03 * b3; c1 += a13 * b3; c2 += a23 * b3; c3 += a33 * b3;

              C[i+0][j] = c0; C[i+1][j] = c1;
              C[i+2][j] = c2; C[i+3][j] = c3;
            }
          }

          /* 4x1 Micro-kernel (Handling remainder bounds of k) */
          for (; k < k_max; k++) {
            DATA_TYPE a0 = alpha * A[i+0][k]; DATA_TYPE a1 = alpha * A[i+1][k];
            DATA_TYPE a2 = alpha * A[i+2][k]; DATA_TYPE a3 = alpha * A[i+3][k];

            #pragma GCC ivdep
            for (int j = jj; j < j_max; j++) {
              DATA_TYPE b0 = B[k][j];
              C[i+0][j] += a0 * b0; C[i+1][j] += a1 * b0;
              C[i+2][j] += a2 * b0; C[i+3][j] += a3 * b0;
            }
          }
        }

        /* Handling remainder bounds of i natively */
        for (; i < i_max; i++) {
          int k = kk;

          /* 1x4 Micro-kernel */
          for (; k <= k_max - 4; k += 4) {
            DATA_TYPE a0 = alpha * A[i][k+0]; DATA_TYPE a1 = alpha * A[i][k+1];
            DATA_TYPE a2 = alpha * A[i][k+2]; DATA_TYPE a3 = alpha * A[i][k+3];

            #pragma GCC ivdep
            for (int j = jj; j < j_max; j++) {
              DATA_TYPE c0 = C[i][j];
              c0 += a0 * B[k+0][j]; c0 += a1 * B[k+1][j];
              c0 += a2 * B[k+2][j]; c0 += a3 * B[k+3][j];
              C[i][j] = c0;
            }
          }

          /* 1x1 Micro-kernel */
          for (; k < k_max; k++) {
            DATA_TYPE a0 = alpha * A[i][k];

            #pragma GCC ivdep
            for (int j = jj; j < j_max; j++) {
              C[i][j] += a0 * B[k][j];
            }
          }
        }

      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
