    DATA_TYPE *C, *A, *B;
} gemm_thread_data_t;


/* Worker loop running on dedicated OS threads */
static int gemm_worker_thread(void* arg) {
    gemm_thread_data_t* data = (gemm_thread_data_t*)arg;
    int ni = data->ni;
    int nj = data->nj;
    int nk = data->nk;
    DATA_TYPE alpha = data->alpha;
    DATA_TYPE beta = data->beta;

    /* Formally cast to C-23 standard Variable Length Array mappings */
    typedef DATA_TYPE (*C_ptr)[nj];
    typedef DATA_TYPE (*A_ptr)[nk];
    typedef DATA_TYPE (*B_ptr)[nj];

    C_ptr C = (C_ptr)data->C;
    A_ptr A = (A_ptr)data->A;
    B_ptr B = (B_ptr)data->B;

    /* Optimized tile factors specifically tuned for L1/L2 caches of AVX/AVX512 CPUs */
    int BLOCK_I = 64;
    int BLOCK_J = 128;
    int BLOCK_K = 128;

    int num_j_blocks = (nj + BLOCK_J - 1) / BLOCK_J;

    /* Dynamic Load Balancing: Threads fetch disjoint blocks atomically. */
    while (1) {
        int block_idx = atomic_fetch_add(data->counter, 1);
        if (block_idx >= data->total_blocks) {
            break; /* No more tiles to process */
        }

        /* Re-create generic 2D block positions bounds from chunk IDs */
        int ib = block_idx / num_j_blocks;
        int jb = block_idx % num_j_blocks;

        int i = ib * BLOCK_I;
        int max_i = (i + BLOCK_I < ni) ? i + BLOCK_I : ni;

        int j = jb * BLOCK_J;
        int max_j = (j + BLOCK_J < nj) ? j + BLOCK_J : nj;

        /* Step 1. First Pass Initialization: Scale C tile chunk against standalone BETA coefficient */
        for (int ii = i; ii < max_i; ii++) {
            DATA_TYPE* restrict c_row = C[ii];
            #pragma GCC ivdep
            for (int jj = j; jj < max_j; jj++) {
                c_row[jj] *= beta;
            }
        }

        /* Step 2. GEMM Engine Kernel with Register Blocking manually unrolled */
        for (int k = 0; k < nk; k += BLOCK_K) {
            int max_k = (k + BLOCK_K < nk) ? k + BLOCK_K : nk;

            int ii = i;

            /* Unroll loop by 8 vector register units horizontally */
            for (; ii <= max_i - 8; ii += 8) {
                for (int kk = k; kk < max_k; kk++) {
                    DATA_TYPE a0 = alpha * A[ii+0][kk];
                    DATA_TYPE a1 = alpha * A[ii+1][kk];
                    DATA_TYPE a2 = alpha * A[ii+2][kk];
                    DATA_TYPE a3 = alpha * A[ii+3][kk];
                    DATA_TYPE a4 = alpha * A[ii+4][kk];
                    DATA_TYPE a5 = alpha * A[ii+5][kk];
                    DATA_TYPE a6 = alpha * A[ii+6][kk];
                    DATA_TYPE a7 = alpha * A[ii+7][kk];

                    DATA_TYPE* restrict c0 = C[ii+0];
                    DATA_TYPE* restrict c1 = C[ii+1];
                    DATA_TYPE* restrict c2 = C[ii+2];
                    DATA_TYPE* restrict c3 = C[ii+3];
                    DATA_TYPE* restrict c4 = C[ii+4];
                    DATA_TYPE* restrict c5 = C[ii+5];
                    DATA_TYPE* restrict c6 = C[ii+6];
                    DATA_TYPE* restrict c7 = C[ii+7];
                    const DATA_TYPE* restrict b0 = B[kk];

                    #pragma GCC ivdep
                    #pragma GCC unroll 4
                    for (int jj = j; jj < max_j; jj++) {
                        DATA_TYPE b_val = b0[jj];
                        c0[jj] += a0 * b_val;
                        c1[jj] += a1 * b_val;
                        c2[jj] += a2 * b_val;
                        c3[jj] += a3 * b_val;
                        c4[jj] += a4 * b_val;
                        c5[jj] += a5 * b_val;
                        c6[jj] += a6 * b_val;
                        c7[jj] += a7 * b_val;
                    }
                }
            }
            /* Edge-handling remainder unrolling logic */
            for (; ii <= max_i - 4; ii += 4) {
                for (int kk = k; kk < max_k; kk++) {
                    DATA_TYPE a0 = alpha * A[ii+0][kk];
                    DATA_TYPE a1 = alpha * A[ii+1][kk];
                    DATA_TYPE a2 = alpha * A[ii+2][kk];
                    DATA_TYPE a3 = alpha * A[ii+3][kk];

                    DATA_TYPE* restrict c0 = C[ii+0];
                    DATA_TYPE* restrict c1 = C[ii+1];
                    DATA_TYPE* restrict c2 = C[ii+2];
                    DATA_TYPE* restrict c3 = C[ii+3];
                    const DATA_TYPE* restrict b0 = B[kk];

                    #pragma GCC ivdep
                    #pragma GCC unroll 4
                    for (int jj = j; jj < max_j; jj++) {
                        DATA_TYPE b_val = b0[jj];
                        c0[jj] += a0 * b_val;
                        c1[jj] += a1 * b_val;
                        c2[jj] += a2 * b_val;
                        c3[jj] += a3 * b_val;
                    }
                }
            }
            for (; ii <= max_i - 2; ii += 2) {
                for (int kk = k; kk < max_k; kk++) {
                    DATA_TYPE a0 = alpha * A[ii+0][kk];
                    DATA_TYPE a1 = alpha * A[ii+1][kk];

                    DATA_TYPE* restrict c0 = C[ii+0];
                    DATA_TYPE* restrict c1 = C[ii+1];
                    const DATA_TYPE* restrict b0 = B[kk];

                    #pragma GCC ivdep
                    #pragma GCC unroll 4
                    for (int jj = j; jj < max_j; jj++) {
                        DATA_TYPE b_val = b0[jj];
                        c0[jj] += a0 * b_val;
                        c1[jj] += a1 * b_val;
                    }
                }
            }
            for (; ii < max_i; ii++) {
                for (int kk = k; kk < max_k; kk++) {
                    DATA_TYPE a0 = alpha * A[ii][kk];
                    DATA_TYPE* restrict c0 = C[ii];
                    const DATA_TYPE* restrict b0 = B[kk];

                    #pragma GCC ivdep
                    #pragma GCC unroll 4
                    for (int jj = j; jj < max_j; jj++) {
                        c0[jj] += a0 * b0[jj];
                    }
                }
            }
        }
    }
    return 0;
}


