  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Struct for transmitting context and block constraints natively to standard pthreads */
typedef struct {
    int id;
    int num_threads;
    int ni;
    int nj;
    int nk;
    DATA_TYPE alpha;
    DATA_TYPE beta;
    void *C;
    void *A;
    void *B;
} thread_arg_t;

/* Explicit GCC vectorization hints targeting typical 32-core x64 architecture */
__attribute__((target("avx2,fma"), optimize("O3,unroll-loops")))
static void* thread_func(void *arg) {
    thread_arg_t *t = (thread_arg_t *)arg;
    int ni = t->ni;
    int nj = t->nj;
    int nk = t->nk;

    // Explicit restrict qualifiers assert no aliasing (facilitating unhindered SIMD generation)
    DATA_TYPE (*restrict C)[nj] = (DATA_TYPE (*)[nj])t->C;
    DATA_TYPE (*restrict A)[nk] = (DATA_TYPE (*)[nk])t->A;
    DATA_TYPE (*restrict B)[nj] = (DATA_TYPE (*)[nj])t->B;
    DATA_TYPE alpha = t->alpha;
    DATA_TYPE beta = t->beta;

    // Mutually exclusive uniform chunking of workload among configured core pool (along 'i' rows)
    int chunk = (ni + t->num_threads - 1) / t->num_threads;
    int start_i = t->id * chunk;
    int end_i = start_i + chunk;
    if (end_i > ni) end_i = ni;

    // Terminate thread instantly if it receives out-of-bounds workload
    if (start_i >= end_i) return NULL;

    // Tiling Constants formulated for general x86-64 L1d (32K) & L2 (512K/1MB) topologies
    int BLK_I = 64;
    int BLK_J = 256;
    int BLK_K = 128;

    for (int i0 = start_i; i0 < end_i; i0 += BLK_I) {
        int i_max = i0 + BLK_I < end_i ? i0 + BLK_I : end_i;

        for (int j0 = 0; j0 < nj; j0 += BLK_J) {
            int j_max = j0 + BLK_J < nj ? j0 + BLK_J : nj;

            // Beta scale is decoupled strictly outside the iterative `k` logic mapped to identical loops
            for (int i = i0; i < i_max; i++) {
                #pragma GCC ivdep
                for (int j = j0; j < j_max; j++) {
                    C[i][j] *= beta;
                }
            }

            for (int k0 = 0; k0 < nk; k0 += BLK_K) {
                int k_max = k0 + BLK_K < nk ? k0 + BLK_K : nk;

                int i = i0;
                // Core Micro-kernel Loop (Unrolled 2x by `i` and 4x by `k`) natively avoids AVX-256 register saturation
                for (; i <= i_max - 2; i += 2) {
                    int k = k0;
                    for (; k <= k_max - 4; k += 4) {
                        DATA_TYPE a00 = alpha * A[i][k];
                        DATA_TYPE a01 = alpha * A[i][k+1];
                        DATA_TYPE a02 = alpha * A[i][k+2];
                        DATA_TYPE a03 = alpha * A[i][k+3];

                        DATA_TYPE a10 = alpha * A[i+1][k];
                        DATA_TYPE a11 = alpha * A[i+1][k+1];
                        DATA_TYPE a12 = alpha * A[i+1][k+2];
                        DATA_TYPE a13 = alpha * A[i+1][k+3];

                        #pragma GCC ivdep
                        for (int j = j0; j < j_max; j++) {
                            DATA_TYPE b0 = B[k][j];
                            DATA_TYPE b1 = B[k+1][j];
                            DATA_TYPE b2 = B[k+2][j];
                            DATA_TYPE b3 = B[k+3][j];

                            C[i][j]   += a00 * b0 + a01 * b1 + a02 * b2 + a03 * b3;
                            C[i+1][j] += a10 * b0 + a11 * b1 + a12 * b2 + a13 * b3;
                        }
                    }
                    // Handle edge cases for inner `k` remainder logic cleanly
                    for (; k < k_max; k++) {
                        DATA_TYPE a00 = alpha * A[i][k];
                        DATA_TYPE a10 = alpha * A[i+1][k];
                        #pragma GCC ivdep
                        for (int j = j0; j < j_max; j++) {
                            DATA_TYPE b0 = B[k][j];
                            C[i][j]   += a00 * b0;
                            C[i+1][j] += a10 * b0;
                        }
                    }
                }
                // Handle edge cases for outer `i` remainder logic cleanly
                for (; i < i_max; i++) {
                    int k = k0;
                    for (; k <= k_max - 4; k += 4) {
                        DATA_TYPE a00 = alpha * A[i][k];
                        DATA_TYPE a01 = alpha * A[i][k+1];
                        DATA_TYPE a02 = alpha * A[i][k+2];
                        DATA_TYPE a03 = alpha * A[i][k+3];
                        #pragma GCC ivdep
                        for (int j = j0; j < j_max; j++) {
                            DATA_TYPE b0 = B[k][j];
                            DATA_TYPE b1 = B[k+1][j];
                            DATA_TYPE b2 = B[k+2][j];
                            DATA_TYPE b3 = B[k+3][j];

                            C[i][j] += a00 * b0 + a01 * b1 + a02 * b2 + a03 * b3;
                        }
                    }
                    for (; k < k_max; k++) {
                        DATA_TYPE a00 = alpha * A[i][k];
                        #pragma GCC ivdep
                        for (int j = j0; j < j_max; j++) {
                            C[i][j] += a00 * B[k][j];
                        }
                    }
                }
            }
        }
    }
    return NULL;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
#pragma scop

    // Remap polybench sizing constraint definitions dynamically
    int pb_ni = _PB_NI;
    int pb_nj = _PB_NJ;
    int pb_nk = _PB_NK;

    int num_threads = 64; // Tuned for generic target (32 Cores + HyperThreading)
    long long total_ops = (long long)pb_ni * pb_nj * pb_nk;

    // Scale thread-pool backwards to 1 iteratively on very small operations to dodge deployment drag
    if (total_ops < 1000000 || pb_ni < num_threads) {
        num_threads = pb_ni < 64 ? pb_ni : 1;
        if (total_ops < 1000000) num_threads = 1;
    }
    if (num_threads <= 0) num_threads = 1;

    // Single-thread dispatcher
    if (num_threads == 1) {
        thread_arg_t arg = {0, 1, pb_ni, pb_nj, pb_nk, alpha, beta, (void*)C, (void*)A, (void*)B};
        thread_func(&arg);
    } 
    // Multi-thread parallel execution pool pipeline
    else {
        pthread_t threads[64];
        thread_arg_t args[64];

        for (int i = 0; i < num_threads; i++) {
            args[i].id = i;
            args[i].num_threads = num_threads;
            args[i].ni = pb_ni;
            args[i].nj = pb_nj;
            args[i].nk = pb_nk;
            args[i].alpha = alpha;
            args[i].beta = beta;
            args[i].C = (void*)C;
            args[i].A = (void*)A;
            args[i].B = (void*)B;
            pthread_create(&threads[i], NULL, thread_func, &args[i]);
        }

        // Blocking Join
        for (int i = 0; i < num_threads; i++) {
            pthread_join(threads[i], NULL);
        }
    }
#pragma endscop
}


